  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Inogatran, the closest structural analogue sharing the cyclohexylalanine-glycine-proline/pipecolate scaffold and an ionizable amidine/guanidine plus carboxylate, had <5% oral bioavailability in healthy volunteers, directly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Melagatran, a related oral thrombin inhibitor with an amidinopiperidine and carboxylate zwitterionic motif, had only 3–7% oral bioavailability in humans, supporting low F for the query's amidine/carboxylate pharmacophore.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "DX-9065a, a non-peptidic inhibitor with strong basic amidino groups and a carboxylate, had 2–3% human oral bioavailability, supporting that the amidine/carboxylate zwitterion in the query severely limits oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "AZD0837, the highest-similarity analogue, achieved 22–55% oral bioavailability, but it is an O-methylamidoxime prodrug; the query has a free amidine, so this high-F evidence is contradictory but weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a free-amidine, zwitterionic peptidomimetic; the closest structural analogues (inogatran, melagatran, DX-9065a) show 0.9–7% oral bioavailability, and the only high-F analogue is a prodrug whose absorption mechanism does not apply to the query's free amidine.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "AZD0837's high oral bioavailability is confounded by prodrug conversion and does not transfer to the free-amidine query.",
    "Active transport, efflux, and food effects are not experimentally characterized for the query.",
    "The exact permeability and dissolution behavior of the query under fasted conditions is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

